"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["71247"],{64887(e){e.exports=JSON.parse('{"id":"FIN-781","slug":"quantitative-tightening","term":"Quantitative Tightening (QT)","also_known_as":["QT"],"difficulty":"Intermediate","definition":"Quantitative tightening (QT) is a monetary policy in which a central bank reduces the amount of financial assets it holds, shrinking its balance sheet and withdrawing money from the financial system.","explanation":["Quantitative tightening is the reverse of quantitative easing. After years of buying bonds to support the economy, central banks may decide to reduce their holdings once the economy has recovered or inflation has risen.","QT can be carried out in two ways. The central bank can let bonds mature without reinvesting the money it receives, which gradually shrinks its holdings. Or it can actively sell bonds in the market, which reduces holdings more quickly.","For example, a central bank holding large amounts of government bonds might stop reinvesting the proceeds from maturing bonds, allowing its holdings to fall by a set amount each month.","QT tends to push long-term interest rates higher, because the central bank is no longer a major buyer of bonds. It works alongside interest rate increases to tighten financial conditions and reduce inflation. Central banks usually carry out QT gradually and with advance notice, because the effects on markets are uncertain and sudden moves could cause financial instability."],"note":"","total":1500,"prev":{"slug":"quantitative-easing","term":"Quantitative Easing (QE)"},"next":{"slug":"quarter-over-quarter-growth","term":"Quarter-over-Quarter Growth"}}')}}]);